import{products,categories,currency,extrasByCategory,extrasByProduct}from"./catalog.js";import*as cart from"./cart.js";const $=selector=>document.querySelector(selector);const dialog=$("#cart-dialog");let toastTimer;function notify(message){$("#toast").textContent=message;$("#toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("#toast").classList.remove("visible"),2300)}function renderProducts(category="all"){const filtered=products.filter(p=>category==="all"||p.category===category);$("#products").innerHTML=filtered.map(p=>`<article class="product"><div class="product-image ${p.category==="drinks"?"beverage-photo":""}">${p.image?`<img src="${p.image}" alt="${p.name}, foto ilustrativa" width="600" height="460" loading="lazy" decoding="async">`:`<div class="photo-placeholder"><span>${p.name}</span><small>Foto em breve</small></div>`}</div><div class="product-info"><h3>${p.name}</h3><p class="product-description">${p.description}</p><div class="product-bottom"><strong class="product-price">${p.price===null?"A confirmar":currency(p.price)}</strong><button ${p.price===null?"disabled":""} class="add-button" data-add="${p.id}" aria-label="Adicionar ${p.name} ao pedido">${p.price===null?"EM BREVE":"+ ADICIONAR"}</button></div></div></article>`).join("")}function renderCart(){const count=cart.count();$("#open-cart").hidden=!count;$(".cart-count").textContent=count;$("#cart-total").textContent=currency(cart.subtotal());$("#dialog-total").textContent=currency(cart.subtotal());$("#review-order").disabled=!count;$("#order-feedback").textContent="";$("#cart-items").innerHTML=cart.items().map(p=>`<div class="cart-item"><div><strong>${p.name}</strong><small>${currency(p.unitPrice*p.quantity)}</small></div><div class="quantity"><button data-change="${p.id}" data-delta="-1" aria-label="Diminuir quantidade de ${p.name}">\u2212</button><output aria-label="Quantidade de ${p.name}">${p.quantity}</output><button data-change="${p.id}" data-delta="1" aria-label="Aumentar quantidade de ${p.name}" ${p.quantity>=99?"disabled":""}>+</button></div>${extrasByProduct[p.id]??extrasByCategory[p.category]?`<div class="item-extras"><strong>Adicionais <small>por unidade</small></strong><div>${(extrasByProduct[p.id]??extrasByCategory[p.category]).map(extra=>`<label><input type="checkbox" data-extra="${extra.id}" data-product="${p.id}" ${cart.selections[p.id].includes(extra.id)?"checked":""}> ${extra.name} <span>+ ${currency(extra.price)}</span></label>`).join("")}</div></div>`:""}</div>`).join("")||'<p class="empty-cart">Seu pedido est\xE1 vazio. Escolha um lanche no card\xE1pio.</p>'}$(".category-list").addEventListener("click",event=>{const button=event.target.closest("[data-category]");if(!button||!categories.includes(button.dataset.category))return;for(const item of document.querySelectorAll(".category")){const active=item===button;item.classList.toggle("active",active);item.setAttribute("aria-pressed",String(active))}renderProducts(button.dataset.category)});$("#products").addEventListener("click",event=>{const button=event.target.closest("[data-add]");if(!button)return;const product=products.find(p=>p.id===button.dataset.add);if(!product||product.price===null)return;const changed=cart.change(product.id,1);renderCart();notify(changed?`${product.name} adicionado ao pedido.`:"Limite de 99 unidades por produto.")});$("#cart-items").addEventListener("click",event=>{const button=event.target.closest("[data-change]");if(!button)return;const{change:id,delta}=button.dataset;cart.change(id,Number(delta));renderCart();const next=[...document.querySelectorAll("[data-change]")].find(b=>b.dataset.change===id&&b.dataset.delta===delta&&!b.disabled);(next||$("#close-cart")).focus()});$("#open-cart").addEventListener("click",()=>{renderCart();dialog.showModal()});$("#close-cart").addEventListener("click",()=>dialog.close());dialog.addEventListener("click",event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});$("#whatsapp-order").addEventListener("click",()=>{if(!cart.count())return;const delivery=$('input[name="fulfillment"]:checked').value==="delivery"?"Entrega":"Retirada";const payments={"pix-later":"Pix na entrega / retirada",pix:"Pix",cash:"Dinheiro",card:"Cart\xE3o"};const payment=payments[$('input[name="payment"]:checked').value];const lines=cart.items().map(p=>`${p.quantity}x ${p.name}${p.extras.length?` (+ ${p.extras.map(e=>e.name).join(", ")})`:""} \u2014 ${currency(p.unitPrice*p.quantity)}`);const message=`Oi, Renato! Quero pedir:

${lines.join("\n")}

Subtotal: ${currency(cart.subtotal())}
${delivery} \xB7 ${payment}${$("#notes").value.trim()?`
Observa\xE7\xE3o: ${$("#notes").value.trim()}`:""}

Pode confirmar se est\xE1 atendendo e o total${delivery==="Entrega"?" com a entrega":""}?`;window.open(`https://wa.me/5588994537456?text=${encodeURIComponent(message)}`,"_blank","noopener,noreferrer");$("#order-feedback").textContent="Seu pedido est\xE1 pronto. Envie a mensagem no WhatsApp para combinar com o Renato."});$("#cart-items").addEventListener("change",event=>{const input=event.target.closest("[data-extra]");if(!input)return;cart.setExtra(input.dataset.product,input.dataset.extra,input.checked);const id=input.dataset.product,extra=input.dataset.extra;renderCart();document.querySelector(`[data-product="${id}"][data-extra="${extra}"]`)?.focus()});dialog.addEventListener("change",()=>{$("#order-feedback").textContent=""});$("#notes").addEventListener("input",()=>{$("#order-feedback").textContent=""});renderProducts();renderCart();if(document.modelContext?.registerTool){const lifecycle=new AbortController;try{Promise.resolve(document.modelContext.registerTool({name:"read_demo_menu",title:"Consultar card\xE1pio",description:"L\xEA produtos e pre\xE7os do card\xE1pio informado e o subtotal do rascunho local. N\xE3o cria nem envia pedidos.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=="object"||Array.isArray(input)||Object.keys(input).length)throw new Error("Informe um objeto vazio.");return{demo:true,currency:"BRL",pricesIn:"centavos",products:products.map(({id,name,price,category})=>({id,name,price,category})),cart:cart.items().map(({id,quantity})=>({id,quantity})),subtotal:cart.subtotal()}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener("pagehide",()=>lifecycle.abort(),{once:true})}catch{}}const menuToggle=$("#menu-toggle");const menuContent=$("#menu-content");function setMenuOpen(open){menuContent.hidden=!open;menuToggle.setAttribute("aria-expanded",String(open));menuToggle.innerHTML=open?'FECHAR CARD\xC1PIO <span aria-hidden="true">\u2212</span>':'ABRIR CARD\xC1PIO <span aria-hidden="true">+</span>'}menuToggle.addEventListener("click",()=>setMenuOpen(menuContent.hidden));document.addEventListener("click",event=>{const link=event.target.closest('a[href="#cardapio"]');if(link)setMenuOpen(true)});$("#popular-products").addEventListener("click",event=>{const button=event.target.closest("[data-add]");if(!button)return;const product=products.find(p=>p.id===button.dataset.add);cart.change(product.id,1);renderCart();notify(`${product.name} adicionado ao pedido.`)});window.addEventListener("renato-cart-updated",renderCart);
